# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_pid() {
    ps -A -o pid=,comm= | gawk 'NF { pid = $1; $1 = ""; sub(/^ +/, ""); print pid "\t" $0 }'
}

_choice_skey() {
    _static_o
}

_choice_stats() {
    _static_o | _argc_util_comp_multi ,
}

_choice_user() {
    if [[ "$ARGC_OS" == "macos" ]]; then
        dscl . -list /Users 2>/dev/null
    elif command -v getent >/dev/null 2>&1; then
        getent passwd | cut -d: -f1
    else
        ps -A -o user= | gawk 'NF { print $1 }'
    fi
}
